/**
 * Jinx Engineer + Summoner: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Engineer
 * Wiki: https://wiki.bloodontheclocktower.com/Summoner
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L118). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { withStorytellerSteps } from '#lib/core/rules/abilities/gained-abilities.ts';
import { ownJinxRules, storytellerGains } from '#lib/core/rules/jinxes/jinxes.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Engineer + Summoner jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'engineer', 'summoner');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('engineer')?.name).toBe('Engineer');
		expect(data.byId.get('summoner')?.name).toBe('Summoner');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['engineer', 'summoner'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['engineer'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['summoner'])).not.toContain(jinx);
	});

	// The Engineer changes the Minions in play; the living Summoner it changes leaves play.
	const ids = ['summoner', 'engineer', 'poisoner', 'chef', 'empath', 'monk', 'imp'];
	const base = scenario(['summoner', 'engineer', 'chef', 'empath', 'monk'], {
		script: scriptOf(ids)
	});
	const removes = (s: Scenario) =>
		s.do(
			(at) => ({
				type: 'AssignCharacter',
				seatId: at.seat('summoner'),
				characterId: 'poisoner',
				by: 'engineer'
			}),
			{ type: 'SetStorytellerAbility', via: 'engineer', characterId: 'summoner' }
		);

	describe('the Storyteller has the Summoner ability once the living Summoner leaves play', () => {
		it("is data in the Summoner's rules", () => {
			// Wiki: "If the living Summoner is removed from play, the Storyteller has the Summoner ability."
			expect(ownJinxRules(base.game, 'summoner', 'engineer', base.characters)).toEqual({
				storytellerHas: { once: 'changed' }
			});
		});

		it('gives the Storyteller the Summoner ability when the Engineer changes its living player', () => {
			// Wiki: "If the living Summoner is removed from play, the Storyteller has the Summoner ability."
			expect(storytellerGains(base.game, base.seat('summoner'), 'engineer', base.characters)).toBe(
				'summoner'
			);
			expect(storytellerGains(base.game, base.seat('chef'), 'engineer', base.characters)).toBe(
				undefined
			);
		});

		it("adds the Summoner's step for the Storyteller once they have it", () => {
			// Wiki: "the Storyteller has the Summoner ability."
			const s = removes(base);
			expect(s.game.storytellerAbilities).toEqual([{ characterId: 'summoner', via: 'engineer' }]);
			const steps = withStorytellerSteps([], s.game, s.characters, 'other');
			expect(steps.map((step) => step.id)).toEqual(['storyteller:engineer:summoner']);
		});

		it('gives nothing for a dead Summoner, or off the jinxed script', () => {
			// Wiki: "If the living Summoner is removed from play"
			const dead = base.dies('summoner');
			expect(storytellerGains(dead.game, dead.seat('summoner'), 'engineer', dead.characters)).toBe(
				undefined
			);
			const plain = scenario(['summoner', 'engineer', 'chef', 'empath', 'monk'], {
				script: scriptOf(['summoner', 'engineer', 'chef', 'empath', 'monk', 'imp'])
			});
			expect(storytellerGains(plain.game, plain.seat('summoner'), 'pithag', plain.characters)).toBe(
				undefined
			);
		});
	});
});
